import string
from typing import List, Tuple

# Generator for valid JSON text inputs targeting json_parse(const char *)
# Goals:
# - Always return a NUL-terminated buffer (C string requirement).
# - Produce syntactically valid JSON covering a wide feature range:
#   objects, arrays, nested structures, strings with escapes, numbers
#   (ints, floats, exponents), booleans, null, empty containers,
#   varied whitespace, duplicate keys, large/small values.
# - Keep size <= 4096 bytes.
# - Deterministic with seed but random across seeds/calls.

MAX_BYTES = 4096


def _rand_ws(r: random.Random) -> str:
    # Random optional whitespace
    ws_chars = [' ', '\t', '\n', '\r']
    return ''.join(r.choice(ws_chars) for _ in range(r.randint(0, 3)))


def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    # Visible ASCII excluding control + backslash/quote sometimes, we add escapes separately
    chars = string.ascii_letters + string.digits + " _-.:/@+*#?$%&()[]{}|^~,"  # include comma/colon sometimes
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(chars) for _ in range(n))


def _rand_string(r: random.Random, allow_escapes: bool = True, max_len: int = 40) -> str:
    # Produce a JSON string with escapes and unicode sequences
    # Keep inside reasonably small to fit within MAX_BYTES when nested
    length = r.randint(0, max_len)
    pieces: List[str] = []
    for _ in range(length):
        choice = r.random()
        if allow_escapes and choice < 0.12:
            esc = r.choice(['\\\"', '\\\\', '\\/','\\b','\\f','\\n','\\r','\\t'])
            pieces.append(esc)
        elif allow_escapes and choice < 0.16:
            # unicode escape
            code = r.randint(0x20, 0xD7FF)
            pieces.append('\\u' + format(code, '04x'))
        else:
            ch = r.choice(string.ascii_letters + string.digits + " _-.:/@+*#?$%&()[]{}|^~")
            # Avoid raw quotes and backslashes (added via escapes when needed)
            if ch == '"' or ch == '\\':
                pieces.append('\\' + ch)
            else:
                pieces.append(ch)
    s = ''.join(pieces)
    return '"' + s + '"'


def _rand_number(r: random.Random) -> str:
    # JSON number grammar: -? (0|[1-9][0-9]*) (.[0-9]+)? ([eE][+-]?[0-9]+)?
    neg = '-' if r.random() < 0.3 else ''
    if r.random() < 0.3:
        int_part = '0'
    else:
        first = str(r.randint(1, 9))
        rest = ''.join(str(r.randint(0, 9)) for _ in range(r.randint(0, 7)))
        int_part = first + rest
    frac = ''
    if r.random() < 0.5:
        frac_digits = ''.join(str(r.randint(0, 9)) for _ in range(r.randint(1, 8)))
        frac = '.' + frac_digits
    exp = ''
    if r.random() < 0.4:
        e = r.choice(['e', 'E'])
        sign = r.choice(['', '+', '-'])
        exp_digits = ''.join(str(r.randint(0, 9)) for _ in range(r.randint(1, 3)))
        exp = e + sign + exp_digits
    return neg + int_part + frac + exp


def _rand_literal(r: random.Random) -> str:
    return r.choice(['true', 'false', 'null'])


def _rand_value(r: random.Random, depth: int) -> str:
    # Weighted selection; limit nesting depth
    if depth <= 0:
        pick = r.random()
        if pick < 0.4:
            return _rand_string(r)
        elif pick < 0.7:
            return _rand_number(r)
        else:
            return _rand_literal(r)

    choice = r.random()
    if choice < 0.28:
        return _rand_string(r)
    elif choice < 0.52:
        return _rand_number(r)
    elif choice < 0.64:
        return _rand_literal(r)
    elif choice < 0.82:
