        return sign + a + '.' + b
    else:  # exp
        a = str(_rand(r, 0, 10**6))
        if a == '0' and _maybe(r, 0.5):
            a = '0'
        exp_sign = _pick(r, ['+', '-', ''])
        e = str(_rand(r, 0, 308))
        if _maybe(r, 0.5):
            mant = a + '.' + ''.join(r.choice(string.digits) for _ in range(_rand(r, 1, 6)))
        else:
            mant = a
        return sign + mant + _pick(r, ['e', 'E']) + exp_sign + e

def _json_primitive(r: random.Random, depth: int) -> str:
    choice = _pick(r, ['string', 'number', 'true', 'false', 'null'])
    if choice == 'string':
        return _json_string(r)
    if choice == 'number':
        return _json_number(r)
    if choice == 'true':
        return 'true'
    if choice == 'false':
        return 'false'
    return 'null'

def _json_value(r: random.Random, depth: int) -> str:
    # Limit nesting to keep it parseable and within size
    if depth <= 0:
        return _json_primitive(r, depth)
    choice = _pick(r, ['primitive', 'object', 'array'])
    if choice == 'primitive':
        return _json_primitive(r, depth)
    if choice == 'object':
        return _json_object(r, depth - 1)
    return _json_array(r, depth - 1)

def _json_members(r: random.Random, depth: int, max_members: int) -> List[str]:
    n = _rand(r, 0, max_members)
    members = []
    used_keys = set()
    for _ in range(n):
        # ensure unique keys for typical object semantics
        key = None
        for _k in range(5):
            candidate = _json_string(r, max_len=16)
            if candidate not in used_keys:
                key = candidate
                used_keys.add(candidate)
                break
        if key is None:
            key = _json_string(r, max_len=16)
        val = _json_value(r, depth)
        members.append(f"{key}:{val}")
    return members

def _json_object(r: random.Random, depth: int) -> str:
    # Mix various value types and nesting.
    # Occasionally include known-interesting keys to exercise string hashing/comparison in downstream containers.
    members = _json_members(r, depth, max_members=_rand(r, 1, 8))
    # Sprinkle some special keys with diverse values
    specials = []
    if _maybe(r, 0.6):
        specials.append('"empty"' + ':' + '[]')
    if _maybe(r, 0.6):
        specials.append('"zero"' + ':' + '0')
    if _maybe(r, 0.5):
        specials.append('"bool"' + ':' + _pick(r, ['true', 'false']))
    if _maybe(r, 0.4):
        specials.append('"null"' + ':' + 'null')
    if _maybe(r, 0.5):
        specials.append('"text"' + ':' + _json_string(r, max_len=24))
    all_members = members + specials
    return '{' + ','.join(all_members) + '}'

def _json_array(r: random.Random, depth: int) -> str:
    length = _rand(r, 0, 10)
    elems = []
    for _ in range(length):
        elems.append(_json_value(r, depth))
    return '[' + ','.join(elems) + ']'

def _top_level_json(r: random.Random) -> str:
    # Choose between object, array, or primitive; parsers often expect any valid JSON value.
    choice = _pick(r, ['object', 'array', 'primitive'])
    max_depth = _rand(r, 1, 4)
    if choice == 'object':
        return _json_object(r, max_depth)
    if choice == 'array':
        return _json_array(r, max_depth)
    return _json_primitive(r, max_depth)

def _add_whitespace_variations(r: random.Random, s: str) -> str:
    # Insert legal JSON whitespace in a few places to test whitespace handling.
    if not s:
        return s
    spaces = [' ', '\t', '\n', '\r']
    # pre/post whitespace
    prefix = ''.join(_pick(r, spaces) for _ in range(_rand(r, 0, 4)))
    suffix = ''.join(_pick(r, spaces) for _ in range(_rand(r, 0, 4)))
    # Optionally add whitespace after commas and colons by simple replacements (limited to keep size small)
    if _maybe(r, 0.5):
        s = s.replace(',', _pick(r, [', ', ',\n', ',\t']))
    if _maybe(r, 0.5):
        s = s.replace(':', _pick(r, [':', ': ', ':\n']))
    return prefix + s + suffix

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build a JSON document within size limit
    for _ in range(10):
        doc = _top_level_json(r)
        doc = _add_whitespace_variations(r, doc)
        b = doc.encode('utf-8')
        if len(b) <= MAX_BYTES:
            return b
        # If too large, reduce depth and try again
    # Fallback: minimal valid JSON
    return b"{}"
